package ch.jalu.configme.configurationdata;

import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import org.junit.Test;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class PropertyListBuilderTest {

    @Test
    public void addTest() {
        PropertyListBuilder builder = new PropertyListBuilder();

        Property<?> property1 = new SimpleTestProperty("property1", "default1");
        Property<?> property2 = new SimpleTestProperty("property2", "default2");
        Property<?> property3 = new SimpleTestProperty("property3", "default3");

        builder.add(property1);
        builder.add(property2);
        builder.add(property3);

        List<Property<?>> result = builder.create();

        assertEquals(3, result.size());
        assertEquals("property1", result.get(0).getPath());
        assertEquals("property2", result.get(1).getPath());
        assertEquals("property3", result.get(2).getPath());
    }

    @Test
    public void addPropertyWithSameNameTest() {
        PropertyListBuilder builder = new PropertyListBuilder();

        Property<?> property1 = new SimpleTestProperty("property1", "default1");

        builder.add(property1);

        try {
            Property<?> property1Duplicate = new SimpleTestProperty("property1", "default1Duplicate");
            builder.add(property1Duplicate);
            fail("Should have thrown an exception when adding duplicate property.");
        } catch (ConfigMeException e) {
            assertEquals("Path at 'property1' already exists", e.getMessage());
        }
    }

    @Test
    public void addNestedPropertyTest() {
        PropertyListBuilder builder = new PropertyListBuilder();

        Property<?> property1 = new SimpleTestProperty("dashboard.property1", "default1");
        Property<?> property2 = new SimpleTestProperty("dashboard.property2", "default2");
        Property<?> property3 = new SimpleTestProperty("settings.property1", "default3");

        builder.add(property1);
        builder.add(property2);
        builder.add(property3);

        List<Property<?>> result = builder.create();

        assertEquals(3, result.size());
        assertEquals("dashboard.property1", result.get(0).getPath());
        assertEquals("dashboard.property2", result.get(1).getPath());
        assertEquals("settings.property1", result.get(2).getPath());
    }

    @Test
    public void addPropertyWithNonexistentParentTest() {
        PropertyListBuilder builder = new PropertyListBuilder();

        try {
            Property<?> property1 = new SimpleTestProperty("nonexistent.property1", "default1");
            builder.add(property1);
            fail("Should have thrown an exception for nonexistent parent.");
        } catch (ConfigMeException e) {
            assertEquals("Unexpected entry found at path 'nonexistent'", e.getMessage());
        }
    }

}


class SimpleTestProperty implements Property<String> {

    private String path;
    private String defaultValue;

    public SimpleTestProperty(String path, String defaultValue) {
        this.path = path;
        this.defaultValue = defaultValue;
    }

    @Override
    public String getPath() {
        return path;
    }

    @Override
    public String getDefaultValue() {
        return defaultValue.toString();
    }
